// @file ./experiments/local-fixture.ts
import { defineExperiment } from "niceeval";
import { gptResearcher } from "../agents/gpt-researcher.ts";

export default defineExperiment({
  description: "Local-document research baseline using the fixture provider",
  agent: gptResearcher({ baseUrl: "http://127.0.0.1:18000" }),
  runs: 1,
});
// @file ./niceeval.config.ts
import { defineConfig } from "niceeval";

export default defineConfig({
  // Add experiments/ with defineExperiment(...) to run evals.
  //
  // TODO(judge): semantic assertions (t.judge.*) are silently skipped until a judge
  // model is configured — an all-green run does not mean the judge ran. Any
  // OpenAI-compatible /chat/completions service works; the key is read from
  // OPENAI_API_KEY unless apiKeyEnv says otherwise.
  // judge: { model: "gpt-5.4-mini" },
});

// @file ./agents/gpt-researcher.ts
import { completeCoverage, defineAgent } from "niceeval/adapter";
import type { Agent } from "niceeval/adapter";

export function gptResearcher(options: { baseUrl: string }): Agent {
  return defineAgent({
    name: "gpt-researcher-report-api",
    coverage: completeCoverage,
    async send(input, ctx) {
      ctx.progress({ message: "Requesting a research report" });
      const response = await fetch(`${options.baseUrl}/report/`, {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
          task: input.text,
          report_type: "research_report",
          report_source: "local",
          tone: "Objective",
          repo_name: "niceeval-fixture",
          branch_name: "main",
          generate_in_background: false,
        }),
        signal: ctx.signal,
      });

      const body = (await response.json()) as { report?: unknown; error?: unknown };
      const report = typeof body.report === "string" ? body.report : "";

      if (!response.ok || !report) {
        ctx.diagnostic({
          code: "report-api-failure",
          level: "error",
          message: "The report API did not return a report.",
        });
        return { status: "failed", events: [] };
      }

      return {
        status: "completed",
        events: [{ type: "message", role: "assistant", text: report }],
      };
    },
  });
}

// @file ./evals/local-policy.eval.ts
import { defineEval } from "niceeval";
import { includes } from "niceeval/expect";

export default [
  defineEval({
    description: "Finds the maintenance commitment in supplied local research material",
    async test(t) {
      await t.send("Which system is scheduled for continued maintenance, and through what date?");
      t.succeeded();
      t.check(t.reply, includes("Orion"));
      t.check(t.reply, includes("2027-12-31"));
    },
  }),
  defineEval({
    description: "Refuses to invent a release date absent from the supplied local material",
    async test(t) {
      await t.send("What is the approved release date for Project Lumen?");
      t.succeeded();
      t.check(t.reply, includes("cannot be determined"));
    },
  }),
];

