// ───────────────────────── 证据覆盖声明 ─────────────────────────

/** 证据通道的覆盖状态。省略(不声明)= unknown,不是 complete——消费侧与 unavailable 同样保守。 */
export type CoverageStatus = "complete" | "partial" | "unavailable";

/** 单个证据通道的覆盖声明:状态 + 可选的人可读原因(如 "stream reconnected mid-turn")。 */
export interface CoverageDeclaration {
  status: CoverageStatus;
  reason?: string;
}

/**
 * 覆盖声明(EvidenceCoverage):完整性不是口头承诺,是随数据走的声明
 * (见 docs/feature/adapters/architecture/evidence.md)。两层:
 * - Agent 级默认(`defineAgent` / `defineSandboxAgent` 的 `coverage`)声明该 Adapter 的常态覆盖;
 *   官方 SDK 适配器显式声明全通道 complete(用 `completeCoverage` 常量)。
 * - Turn 级降级(`Turn.coverage`)只用于相对 Agent 默认值降级(这一轮流断了 / 拿不到 usage),
 *   不能把 Agent 未声明的通道升格成 complete。
 * 整个 Agent 不声明时全部通道视为 unknown。
 */
export interface EvidenceCoverage {
  /** 完整事件流(event / notEvent / order 的依据)。 */
  events?: CoverageDeclaration;
  /** action 生命周期(工具正负断言、顺序、失败的依据)。 */
  actions?: CoverageDeclaration;
  /** assistant / user message(reply、messageIncludes 的依据)。 */
  messages?: CoverageDeclaration;
  /** usage(token / cost 上限断言的依据)。 */
  usage?: CoverageDeclaration;
  /** Turn status 的真实性(succeeded / parked 的依据)——恒 completed 的映射必须声明非 complete。 */
  status?: CoverageDeclaration;
  /** Turn.data(outputEquals / outputMatches 的依据)。 */
  data?: CoverageDeclaration;
}

/** 随一轮消息附带的文件(图片等多模态输入)。 */
export interface InputFile {
  /** 文件名(可选,供 adapter / 模型参考)。 */
  readonly filename?: string;
  /** MIME 类型,如 `image/png`、`image/jpeg`。 */
  readonly mimeType: string;
  /** base64 编码的文件内容(JSON 友好,remote adapter 可直接放进请求体)。 */
  readonly dataBase64: string;
}

/**
 * HITL 回答轮里,人的裁决以结构化形式随 `input.responses` 到达——adapter 不需要解析
 * `text` 去猜哪句回答对应哪个请求、算不算批准。见 docs-site/zh/explanation/adapter.mdx
 * 「不同回答的入参」一节的四种典型形态。
 */
export interface InputResponse {
  /** 对应哪条 input.requested 请求;多个请求并停时靠它对位。 */
  readonly requestId: string;
  /** 与 text 二选一:回答命中了请求 options 里的某个 id(approve / deny…)。 */
  readonly optionId?: string;
  /** 与 optionId 二选一:自由文本回答(请求没有选项,或回答不是任何选项)。 */
  readonly text?: string;
}

export interface TurnInput {
  readonly text: string;
  /** 本轮附带的文件(图片等)。adapter 自行决定怎么投递;不支持多模态的 adapter 忽略它。 */
  readonly files?: readonly InputFile[];
  /** 仅回答轮(t.respond / t.respondAll):逐请求的结构化回答,按 requestId 对位。 */
  readonly responses?: readonly InputResponse[];
}

/** adapter 的 send 返回值(事件流为核心)。 */
export interface Turn {
  readonly events: StreamEvent[];
  readonly data?: unknown;
  readonly status: "completed" | "failed" | "waiting";
  readonly usage?: Usage;
  /**
   * 本轮相对 Agent 默认覆盖的降级声明(这一轮流断了、拿不到 usage 等);
   * 只能降级,不能把 Agent 未声明的通道升格成 complete(见 EvidenceCoverage)。
   */
  readonly coverage?: EvidenceCoverage;
}

/**
 * 本次运行的 OTLP traces 接收信息(仅当配置了 OTel 接入时有——agent 的 `tracing` 块 /
 * config 的 telemetry 存在)。经 ctx.telemetry 交给 agent。span 只进瀑布图,不喂断言。
 * 远程 HTTP 接入的 send 只需要 spread `headers`(每轮一个新 traceparent);接收端点是
 * 启动期配置(`defineConfig({ telemetry: { port } } )`)固定的,不从这里传。
 */
export interface Telemetry {
  /** 接收端点(完整路径,形如 http://host.docker.internal:PORT/v1/traces)。 */
  readonly endpoint: string;
  /**
   * env-based 导出的 env(= AgentTracing.env(endpoint) 的结果),ready-to-spread。
   * adapter 的 send 直接 `{ ...ctx.telemetry?.env }` 注入,不必手搓 OTEL_* 拼装。
   */
  readonly env?: Readonly<Record<string, string>>;
  /**
   * 本轮的 W3C trace context(traceparent),每轮一个新值。send 把它 spread 进 HTTP 请求头
   * (或注入子进程 env)——应用埋点支持 context 传播时,本轮 span 挂到我们给的 trace 下,
   * 并发跑 eval 的 span 归属才精确;不带则回退时间窗口归属(该 agent 自动降为串行)。
   */
  readonly headers?: Readonly<Record<string, string>>;
}

/**
 * agent 的 OTLP 导出配置 —— 「沙箱里怎么让这个 CLI 把 trace 发到 endpoint」。
 * 刻意从 setup 里拆出来:setup 管装 CLI / 写主配置,这里只管 otel 导出。两种投递方式
 * (互不排斥,按 CLI 而定):
 *   · env-based(标准 OTEL_* 环境变量,如 bub/Python OTel SDK)—— 用 `env`;
// 证据覆盖的解析与折叠:Agent 级默认 + Turn 级降级 → attempt 级聚合
// (见 docs/feature/adapters/architecture/evidence.md「覆盖声明」)。
// 消费规则(正/负断言的三值折叠)在 scoped.ts;这里只管状态代数:
// unknown/unavailable < partial < complete,Turn 只能降级、聚合取最差。

import type { CoverageDeclaration, CoverageStatus, EvidenceCoverage } from "../agents/types.ts";

/** 证据通道全集(EvidenceCoverage 的键)。 */
export const COVERAGE_CHANNELS = ["events", "actions", "messages", "usage", "status", "data"] as const;
export type CoverageChannel = (typeof COVERAGE_CHANNELS)[number];

/**
 * 解析后的通道状态:未声明按 "unknown" 落地(不是 complete)。unknown 与 unavailable 在
 * 消费侧同样保守;区别只在展示(unknown =「Adapter 没说」,unavailable =「Adapter 说了拿不到」)。
 */
export type ResolvedCoverageStatus = CoverageStatus | "unknown";

/** 解析后的单通道声明。 */
export interface ResolvedCoverageChannel {
  status: ResolvedCoverageStatus;
  reason?: string;
}

/** 全通道解析后的覆盖:每个通道必有一个状态(缺省 unknown)。 */
export type ResolvedCoverage = Readonly<Record<CoverageChannel, ResolvedCoverageChannel>>;

/**
 * 官方 SDK 适配器用的「全通道 complete」常量:完整事件流、完整 steps/output、经过生命周期
 * fixture 验证的 transcript 才可以声明它(见 docs/feature/adapters/architecture/evidence.md)。
 */
export const completeCoverage: EvidenceCoverage = Object.freeze<EvidenceCoverage>({
  events: { status: "complete" },
  actions: { status: "complete" },
  messages: { status: "complete" },
  usage: { status: "complete" },
  status: { status: "complete" },
  data: { status: "complete" },
});

// 状态序:折叠一律取最差。unknown 与 unavailable 保守程度相同,并列最差;
// 并列时取「有声明的那一个」(unavailable 带 reason,信息量更大)。
const RANK: Record<ResolvedCoverageStatus, number> = {
  complete: 3,
  partial: 2,
  unavailable: 1,
  unknown: 1,
};

function worseOf(a: ResolvedCoverageChannel, b: ResolvedCoverageChannel): ResolvedCoverageChannel {
  const ra = RANK[a.status];
  const rb = RANK[b.status];
  if (ra < rb) return a;
  if (rb < ra) return b;
  // 并列:优先「Adapter 说了拿不到」(unavailable / 带 reason)而不是「没说」。
  if (a.status === "unknown" && b.status !== "unknown") return b;
  if (b.status === "unknown" && a.status !== "unknown") return a;
  return a.reason !== undefined ? a : b;
}

/** Agent 级声明 → 全通道解析(未声明通道 = unknown)。 */
export function resolveAgentCoverage(declared: EvidenceCoverage | undefined): ResolvedCoverage {
  const out = {} as Record<CoverageChannel, ResolvedCoverageChannel>;
  for (const ch of COVERAGE_CHANNELS) {
    const d: CoverageDeclaration | undefined = declared?.[ch];
    out[ch] = d ? { status: d.status, ...(d.reason !== undefined ? { reason: d.reason } : {}) } : { status: "unknown" };
  }
  return out;
}

/**
 * Turn 级降级:相对 base(Agent 默认)只能变差,不能升格——Turn 声明比 base 更好的状态
 * 直接被 base 压住(min 语义天然满足「不能把 Agent 未声明的通道升格成 complete」)。
 */
export function downgradeCoverage(base: ResolvedCoverage, turn: EvidenceCoverage | undefined): ResolvedCoverage {
  if (!turn) return base;
  const out = {} as Record<CoverageChannel, ResolvedCoverageChannel>;
  for (const ch of COVERAGE_CHANNELS) {
    const d = turn[ch];
    out[ch] = d ? worseOf(base[ch], { status: d.status, ...(d.reason !== undefined ? { reason: d.reason } : {}) }) : base[ch];
  }
  return out;
}

/** attempt / session 级聚合:各 turn 的最差值(unknown/unavailable < partial < complete)。 */
export function worstCoverage(list: readonly ResolvedCoverage[]): ResolvedCoverage {
  if (list.length === 0) return resolveAgentCoverage(undefined);
  let acc = list[0]!;
  for (let i = 1; i < list.length; i++) {
    const next = list[i]!;
    const out = {} as Record<CoverageChannel, ResolvedCoverageChannel>;
    for (const ch of COVERAGE_CHANNELS) out[ch] = worseOf(acc[ch], next[ch]);
    acc = out;
  }
  return acc;
}
